    function toast(message,isError){var node=q('#toast');node.textContent=message;node.className='toast'+(isError?' error':'');clearTimeout(window.__apiToastTimer);window.__apiToastTimer=setTimeout(function(){node.className='toast hidden'},3100)}
    function normalize(document){var endpoints=[];Object.keys(document.paths||{}).forEach(function(path){var item=document.paths[path]||{};Object.keys(item).forEach(function(method){if(!/^(get|post|put|patch|delete)$/i.test(method))return;var operation=item[method]||{};var tag=(operation.tags&&operation.tags[0])||'System';endpoints.push({id:method.toUpperCase()+' '+path,group:tag,method:method.toUpperCase(),path:path,summary:operation.summary||'Untitled endpoint',description:operation.description||operation.summary||'No additional endpoint description is declared in the current OpenAPI contract.',auth:Array.isArray(operation.security)&&operation.security.length>0,parameters:operation.parameters||[],requestBody:operation.requestBody||null,responses:operation.responses||{}})});});return endpoints}
