    function sampleValue(name,schema){if(schema&&schema.example!==undefined)return schema.example;if(schema&&schema.default!==undefined)return schema.default;if(schema&&schema.enum&&schema.enum.length)return schema.enum[0];if(schema&&schema.type==='boolean')return true;if(schema&&['integer','number'].indexOf(schema.type)>=0)return 1;if(schema&&schema.format==='uuid')return '00000000-0000-4000-8000-000000000001';if(/reason/i.test(name))return 'Administrative update requested from API Explorer';if(/display.?name/i.test(name))return 'Example Instructor';if(/title/i.test(name))return 'Example course';if(/code/i.test(name))return 'EXAMPLE-001';if(/status/i.test(name))return 'active';return 'example'}
