    function codeMarkup(label,code,copyId){var lines=String(code).split('\n');return '<div class="code-block"><div class="code-block-header"><span>'+escapeHtml(label)+'</span><button class="copy-button" type="button" data-copy="'+escapeHtml(copyId)+'">'+copyIcon+' Copy</button></div><pre id="'+escapeHtml(copyId)+'">'+lines.map(function(line,index){return '<span class="code-line"><span class="line-number">'+(index+1)+'</span><span>'+highlightJson(line||' ')+'</span></span>'}).join('')+'</pre></div>'}
    function requestSample(endpoint){var body=requestExample(endpoint);var url=location.origin+endpoint.path.replace(/\{[^}]+\}/g,'{id}');var headers=['Accept: application/json'];if(endpoint.auth)headers.push('Authorization: Bearer &lt;access-token&gt;');if(['POST','PUT','PATCH','DELETE'].indexOf(endpoint.method)>=0)headers.push('Content-Type: application/json');if(['POST','PUT','PATCH','DELETE'].indexOf(endpoint.method)>=0)headers.push('Idempotency-Key: &lt;unique-key&gt;');if(state.sampleMode==='curl'){var parts=['curl -X '+endpoint.method+' '+JSON.stringify(url)];headers.forEach(function(header){parts.push('  -H '+JSON.stringify(header))});if(Object.keys(body).length)parts.push('  -d '+JSON.stringify(JSON.stringify(body)));return parts.join(' \\\n')}if(state.sampleMode==='fetch'){return 'fetch('+JSON.stringify(url)+', {\n  method: '+JSON.stringify(endpoint.method)+',\n  headers: '+pretty(headers.reduce(function(result,header){var index=header.indexOf(': ');result[header.slice(0,index)]=header.slice(index+2);return result},{}))+',\n  body: '+(Object.keys(body).length?JSON.stringify(JSON.stringify(body,null,2)):'undefined')+'\n})'}return 'const response = await fetch('+JSON.stringify(url)+', {\n  method: '+JSON.stringify(endpoint.method)+',\n  headers: '+pretty(headers.reduce(function(result,header){var index=header.indexOf(': ');result[header.slice(0,index)]=header.slice(index+2);return result},{}))+',\n  body: '+(Object.keys(body).length?JSON.stringify(JSON.stringify(body,null,2)):'undefined')+'\n});\nconst payload = await response.json();'}
    function schemaRows(schema,required,depth,keyPrefix){if(!schema||!schema.properties)return '<div class="schema-empty">No detailed object properties are declared for this part of the contract.</div>';var html='<div class="schema-object-label">object</div>';Object.keys(schema.properties).forEach(function(name){var property=schema.properties[name]||{};var childKey=keyPrefix+'-'+name;var hasChildren=Boolean(property.properties);var expanded=state.expanded[childKey]!==false;var label=hasChildren?'<button class="schema-toggle" type="button" data-schema-toggle="'+escapeHtml(childKey)+'" aria-expanded="'+expanded+'">'+chevron+escapeHtml(name)+'</button>':escapeHtml(name);html+='<div class="schema-row" style="padding-left:'+(13+depth*13)+'px"><span class="schema-name">'+label+'</span><span class="schema-type">'+escapeHtml(property.type||property.format||'object')+'</span><span>'+(required&&required.indexOf(name)>=0?'<span class="required-badge">required</span>':'')+'</span><span class="schema-description">'+escapeHtml(property.description||'—')+'</span></div>';if(hasChildren&&expanded)html+='<div class="schema-children">'+schemaRows(property,property.required||[],depth+1,childKey)+'</div>'});return html}
