    function chooseEndpoint(id){state.selected=state.endpoints.filter(function(endpoint){return endpoint.id===id})[0]||state.endpoints[0];state.activeTab='overview';state.requestType='application/json';state.responseStatus=Object.keys(state.selected.responses||{})[0]||'200';state.tryOpen=false;state.form={};state.response=null;state.groupsOpen[state.selected.group]=true;renderNavigation();renderDocumentation()}
